/* Pixel-style quiz - 3-5 color palette: #1a1a2e, #16213e, #e94560, #f5f5f5, #0f3460 */
* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: 'Courier New', monospace;
  font-size: 18px;
  padding: 16px;
}

.quiz-card {
  background: #16213e;
  border: 4px solid #e94560;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 #0f3460;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.question {
  color: #f5f5f5;
  font-size: 28px;
  font-weight: bold;
  margin-bottom: 24px;
  letter-spacing: 2px;
  min-height: 44px;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

.answer-btn {
  background: #0f3460;
  color: #f5f5f5;
  border: 3px solid #e94560;
  padding: 12px 28px;
  font-family: inherit;
  font-size: 20px;
  font-weight: bold;
  cursor: pointer;
  min-width: 80px;
  transition: background 0.1s, transform 0.1s;
}

.answer-btn:hover:not(:disabled) {
  background: #e94560;
  color: #1a1a2e;
}

.answer-btn:focus-visible {
  outline: 3px solid #f5f5f5;
  outline-offset: 2px;
}

.answer-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
}

.answer-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.score {
  color: #e94560;
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 24px;
}

.score::before { content: 'Score: '; color: #f5f5f5; }

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.control-btn {
  background: #0f3460;
  color: #f5f5f5;
  border: 3px solid #e94560;
  padding: 10px 24px;
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
}

.control-btn:hover:not(:disabled) {
  background: #e94560;
  color: #1a1a2e;
}

.control-btn:focus-visible {
  outline: 3px solid #f5f5f5;
  outline-offset: 2px;
}

.control-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
}

.control-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

@media (max-width: 400px) {
  .quiz-card { padding: 24px 16px; }
  .question { font-size: 24px; }
  .answer-btn { padding: 10px 20px; min-width: 64px; }
}

(function () {
  'use strict';

  var state = {
    questionIndex: 0,
    answered: false,
    score: 0
  };

  var questions = [
    { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  ];

  var questionEl = document.getElementById('question');
  var answerA = document.getElementById('answer-a');
  var answerB = document.getElementById('answer-b');
  var scoreEl = document.getElementById('score');
  var nextBtn = document.getElementById('next');
  var restartBtn = document.getElementById('restart');

  function renderQuestion() {
    var q = questions[state.questionIndex];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    answerA.disabled = false;
    answerB.disabled = false;
    state.answered = false;
    nextBtn.disabled = true;
  }

  function updateScore() {
    scoreEl.textContent = String(state.score);
  }

  function handleAnswer(choice) {
    if (state.answered) return;
    state.answered = true;
    answerA.disabled = true;
    answerB.disabled = true;
    var q = questions[state.questionIndex];
    if (choice === q.correct) {
      state.score += 1;
      updateScore();
    }
    nextBtn.disabled = false;
  }

  answerA.addEventListener('click', function () {
    handleAnswer('a');
  });

  answerB.addEventListener('click', function () {
    handleAnswer('b');
  });

  nextBtn.addEventListener('click', function () {
    if (state.questionIndex === 0) {
      state.questionIndex = 1;
      renderQuestion();
    } else {
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
      nextBtn.disabled = true;
    }
  });

  restartBtn.addEventListener('click', function () {
    state.questionIndex = 0;
    state.answered = false;
    state.score = 0;
    updateScore();
    renderQuestion();
  });

  // Initial state
  renderQuestion();
  updateScore();
})();
